/** Object used to configure which analysis appear in the browser */
object RebecaosConfig extends Configurator[St]:
  val name = "RebeCaos: an animator of Rebeca's semantics"
  override val languageName: String = "Input Rebeca program"

  /** Parser, converting a string into a System in rebecaOS */
  val parser =
//    str => (rebecaos.syntax.Parser.parseProgram(str),Map())
    str => initSt(rebecaos.syntax.Parser.parseProgram(str))

  /** Examples of programs that the user can choose from. The first is the default one. */
  val examples = List(
    "Simple" -> "reactiveclass Example {\n  knownrebecs { Example ex;}\n  statevars { int counter; }\n  msgsrv initial() {\n    counter=0;\n    ex.add(1);}\n  msgsrv add(int a) {\n    if ( counter < 100) \n      {counter = counter + a;}\n  }\n}\n\nmain {\n  Example ex1(ex2):();\n  Example ex2(ex1):();\n}"
      -> "Simple example of a Rebeca program, borrowed from the paper <a href=\"https://cs.rit.edu/~hh/papers/HojjatETAL07Sarir.pdf\">\"Sarir: A Rebeca to mCRL2 Translator\" (ACSD 2007)</a>. This includes a few adaptations from the original paper, e.g., initialising the counter in the <code>initial</code> method.",
    "[Dyn] Simple" -> "reactiveclass Example {\n  knownrebecs {}\n  statevars {\n    int counter;\n    Example target;\n  }\n  msgsrv initial() {\n    counter=0;\n    target = self;\n    target.add(1);}\n  msgsrv add(int a) {\n    counter = counter + a;\n    if ( counter == 1) \n      target = new Example():();\n    target.add(1);\n  }\n}\n\nmain {\n  Example ex1():();\n}"
       -> "Variation of the \"Simple\" example of a Rebeca program from the paper <a href=\"https://cs.rit.edu/~hh/papers/HojjatETAL07Sarir.pdf\">\"Sarir: A Rebeca to mCRL2 Translator\" (ACSD 2007)</a>. This version keeps creating new Example rebecs dynamically every 1-2 counts.",
    "[Reach] Simple" -> "reactiveclass Example {\n  knownrebecs { Example ex;}\n  statevars { int counter; }\n  msgsrv initial() {\n    counter=0;\n    ex.add(1);}\n  msgsrv add(int a) {\n    if ( counter < 100) \n      {counter = counter + a;}\n  }\n}\n\nmain {\n  Example ex1(ex2):();\n  Example ex2(ex1):();\n}\n\nreaches ex1.counter > 1;\nreaches ex1.counter==1;\nreaches ex2.counter==1;\nreaches deadlock;"
       -> "Variation of the \"Simple\" example of a Rebeca program from the paper <a href=\"https://cs.rit.edu/~hh/papers/HojjatETAL07Sarir.pdf\">\"Sarir: A Rebeca to mCRL2 Translator\" (ACSD 2007)</a>. This version includes four reachability properties that can be checked in the widget \"Reachability checks\".",
//    "[Reach] Simple" -> "reactiveclass Example {\n  knownrebecs {}\n  statevars {\n    int counter;\n    Example target;\n  }\n  msgsrv initial() {\n    counter=0;\n    target = self;\n    target.add(1);}\n  msgsrv add(int a) {\n    counter = counter + a;\n    if ( counter == 1) \n      target = new Example():();\n    target.add(1);\n  }\n}\n\nmain {\n  Example ex1():();\n}\n\nreaches ex1.counter >= 2;\nreaches v0.counter >= 2;"
//       -> "Variation of the \"Simple\" example of a Rebeca program from the paper <a href=\"https://cs.rit.edu/~hh/papers/HojjatETAL07Sarir.pdf\">\"Sarir: A Rebeca to mCRL2 Translator\" (ACSD 2007)</a>. This version keeps creating new Example rebecs dynamically every 1-2 counts, and includes 2 reachability properties that can be verified in the widget \"Reachability checks\".",
    "Prod-Cons" -> "reactiveclass Producer {\n  knownrebecs {\n    Consumer consumer;\n  }\n  statevars {\n    byte p;\n  }\n  msgsrv initial() {\n    self.produce();\n  }\n  msgsrv produce() {\n    // produce data\n    p=?(1,2,3,4);\n    consumer.consume(p);\n    self.produce();\n  }\n}\n\nreactiveclass Consumer {\n  knownrebecs {\n  }\n  statevars {\n    byte p;\n  }\n  msgsrv initial() {\n  }\n  msgsrv consume(byte data) {\n    // consume data\n    p = data;\n  }\n}\n\nmain {\n  Producer prod(cons):();\n  Consumer cons():();\n}"
      -> "Producer-consumer example from the paper <a href=\"https://link.springer.com/chapter/10.1007/978-3-540-74792-5_5\">Rebeca: Theory, Applications, and Tools (FMCO 2006)</a>",
    "[Dyn] Prod-Cons" -> "reactiveclass Producer {\n  knownrebecs {\n    Consumer consumer;\n  }\n  statevars {\n    byte p;\n    Producer newProducer;\n  }\n  msgsrv initial() {\n    self.produce();\n  }\n  msgsrv produce() {\n    // produce data\n    p=?(1,2,3,4);\n    if (p==3) {\n      newProducer = new Producer(consumer):();\n    }\n    consumer.consume(p);\n    if(p!=4){\n      self.produce();\n    }\n  }\n}\n\nreactiveclass Consumer {\n  knownrebecs {\n  }\n  statevars {\n    byte p;\n  }\n  msgsrv initial() {\n  }\n  msgsrv consume(byte data) {\n    // consume data\n    p = data;\n  }\n}\n\nmain {\n  Producer prod(cons):();\n  Consumer cons():();\n}"
      -> "Dynamic version of the producer-consumer example from the paper <a href=\"https://link.springer.com/chapter/10.1007/978-3-540-74792-5_5\">Rebeca: Theory, Applications, and Tools (FMCO 2006)</a>",
    "[Time] Ticket service" -> "reactiveclass TicketService {\n  knownrebecs {\n    Agent a;\n  }\n  statevars {\n    int issueDelay;\n  }\n  msgsrv initial(int myDelay) {\n    issueDelay = myDelay;\n  }\n  msgsrv requestTicket() {\n    delay(issueDelay);\n    a.ticketIssued (1);\n  }\n}\nreactiveclass Agent {\n  knownrebecs {\n    TicketService ts;\n    Customer c;\n  }\n  msgsrv requestTicket() {\n    ts.requestTicket()\n      deadline (5);\n  }\n\n  msgsrv ticketIssued(byte id) {\n    c.ticketIssued(id);\n  }\n}\nreactiveclass Customer {\n  knownrebecs {\n    Agent a;\n  }\n  msgsrv initial() {\n    self.try();\n  }\n  msgsrv try() {\n    a.requestTicket();\n  }\n  msgsrv ticketIssued(byte id) {\n    self.try() after(30);\n  }\n}\nmain {\n  Agent a(ts, c):();\n  TicketService ts(a):(3);\n  Customer c(a):();\n}"
      -> "Ticket Service example from the paper <a href=\"https://www.sciencedirect.com/science/article/pii/S0167642314003153\">\"Timed Rebeca schedulability and deadlock freedom analysis using bounded floating time transition system\" (SCP 2015)</a>.",
    "Untimed Ticket Service" -> "reactiveclass TicketService {\n  knownrebecs {\n    Agent a;\n  }\n  statevars {\n  }\n  msgsrv initial() {\n  }\n  msgsrv requestTicket() {\n    a.ticketIssued (1);\n  }\n}\nreactiveclass Agent {\n  knownrebecs {\n    TicketService ts;\n    Customer c;\n  }\n  msgsrv requestTicket() {\n    ts.requestTicket();\n  }\n\n  msgsrv ticketIssued(byte id) {\n    c.ticketIssued(id);\n  }\n}\nreactiveclass Customer {\n  knownrebecs {\n    Agent a;\n  }\n  msgsrv initial() {\n    self.try();\n  }\n  msgsrv try() {\n    a.requestTicket();\n  }\n  msgsrv ticketIssued(byte id) {\n    self.try();\n  }\n}\nmain {\n  Agent a(ts, c):();\n  TicketService ts(a):();\n  Customer c(a):();\n}"
      -> "Untimed version of the Ticket Service example from the paper <a href=\"https://www.sciencedirect.com/science/article/pii/S0167642314003153\">\"Timed Rebeca schedulability and deadlock freedom analysis using bounded floating time transition system\" (SCP 2015)</a>.",
    "Sender-receiver" -> "reactiveclass SenderAgent(3) {\n  knownrebecs { ReceiverAgent receiverAgent; }\n  statevars {\n    boolean receivedAck; \n    int sendDelay;\n  }\n  msgsrv initial() {\n    receivedAck = false;\n    self.start();\n  }\n  msgsrv start() {\n    sendDelay = ?(-1,2,3,4); // -1=fail -- 2,3,4=delays\n    if (sendDelay != -1) {\n      receiverAgent.send() after(sendDelay);\n    }\n    self.checkAck() after(8);\n  }\n  msgsrv ack() { receivedAck = true; }\n  msgsrv checkAck() {\n    if (!receivedAck) self.start();\n  }\n}\nreactiveclass ReceiverAgent(3) {\n  knownrebecs { SenderAgent senderAgent; }\n  statevars {int sendDelay;}\n  msgsrv initial() {}\n  msgsrv send() {\n    sendDelay = ?(-1,1,2,3); // -1=fail -- 1,2,3=delays\n    if (sendDelay != -1) {\n      senderAgent.ack() after(sendDelay);\n    }\n  }\n}\nmain {\n  ReceiverAgent receiverAgent(senderAgent):();\n  SenderAgent senderAgent(receiverAgent):();\n}"
      -> "Simple communication protocol, described in <a href=\"https://link.springer.com/chapter/10.1007/3-540-49538-X_16\">\"Time and asynchrony in interactions among distributed real-time objects\"</a>, used as an example for Rebeca in <a href=\"https://www.sciencedirect.com/science/article/pii/S0167642314000239\">\"Modelling and simulation of asynchronous real-time systems\nusing Timed Rebeca\" (SCP 2014)</a>.",
    "Dining Philosophers" -> "reactiveclass Philosopher(3)\n{\n  knownrebecs\n  {\n    Fork forkL;\n    Fork forkR;\n  }\n  statevars\n  {\n    boolean eating;\n    boolean fL;\n    boolean fR;\n  }\n  msgsrv initial()\n  {\n    fL = false;\n    fR = false;\n    eating = false;\n    self.arrive();\n  }\n\n  msgsrv arrive()\n  {\n    forkL.request();\n  }\n\n  msgsrv permit()\n  {\n    if (sender == forkL) {\n      if (!fL) {\n        fL = true;\n        forkR.request();\n      }\n    }\n    else {\n      if (fL && !(fR)) {\n        fR = true;\n        self.eat();\n      }\n      // else discard the message\n    }\n  }\n\n  msgsrv eat()\n  {\n    eating = true;\n    self.leave();\n  }\n\n  msgsrv leave()\n  {\n    fL = false;\n    fR = false;\n    eating = false;\n    forkL.release();\n    forkR.release();\n    self.arrive();\n  }\n}\n\nreactiveclass Fork(3)\n{\n  knownrebecs\n  {\n    Philosopher philL;\n    Philosopher philR;\n  }\n  statevars\n  {\n    boolean lAssign;  \n    boolean rAssign;  \n    boolean leftReq;\n    boolean rightReq;\n  }\n  msgsrv initial()\n  { \n    lAssign = false;\n    rAssign = false;\n    leftReq = false;\n    rightReq = false;\n  }\n\n  msgsrv request()\n  {\n    if (sender == philL) {\n      if (!leftReq) {\n        leftReq = true;\n        if (!rAssign) {\n          lAssign = true;\n          philL.permit();\n        }\n      } \n      // else discard message\n    }\n    else {\n      if (!rightReq) {\n        rightReq = true;\n        if (!lAssign) {\n          rAssign = true;\n          philR.permit();\n        }\n      }\n      // else discard message\n    }\n  }\n  msgsrv release()\n  {\n    if (sender == philL && lAssign){\n      leftReq = false;\n      lAssign = false;\n      if (rightReq) {\n        rAssign=true;\n        philR.permit();\n      }\n    }\n    if (sender == philR && rAssign){\n      rAssign = false;\n      rightReq = false;\n      if (leftReq) {\n        lAssign=true;\n        philL.permit();\n      }\n    }\n  }\n}\n\nmain\n{\n  Philosopher phil0(fork0, fork2):();\n  Philosopher phil1(fork0, fork1):();\n  Philosopher phil2(fork1, fork2):();\n\n  Fork fork0(phil0, phil1):();\n  Fork fork1(phil1, phil2):();\n  Fork fork2(phil2, phil0):();\n}"
      -> "Dining philosophers, taken from <a href=\"https://rebeca-lang.org/examples\">https://rebeca-lang.org/examples</a>. Unlike core Rebeca, this example requires references to rebecs to be compared in data expressions.",
    "Trains" -> "reactiveclass BridgeController(5) {\n  knownrebecs {\n    Train t1;\n    Train t2;\n  }\n\n  statevars {\n    boolean isWaiting1;\n    boolean isWaiting2;\n    boolean isOnBridge1;\n    boolean isOnBridge2;\n  }\n\n  msgsrv initial() {\n    isOnBridge1 = false;  // red\n    isOnBridge2 = false;  // red\n    isWaiting1 = false;\n    isWaiting2 = false;\n  }\n  \n  msgsrv Arrive() {\n    if (sender == t1){\n      if (isOnBridge2 == false) {\n        isOnBridge1 = true; // green\n        t1.YouMayPass();\n      }\n      else {\n        isWaiting1 = true;\n      }\n    }\n    else {\n      if (isOnBridge1 == false){\n        isOnBridge2 = true; // green\n        t2.YouMayPass();\n      }\n      else{\n        isWaiting2 = true;\n      }\n    }\n  }\n  \n  msgsrv Leave() {\n    if (sender == t1) {\n      isOnBridge1 = false;  // red\n      if (isWaiting2){\n        isOnBridge2 = true;\n        t2.YouMayPass();\n        isWaiting2 = false;\n      }\n    } else {\n      isOnBridge2 = false;  // red\n      if (isWaiting1) {\n        isOnBridge1 = true;\n        t1.YouMayPass();\n        isWaiting1 = false;\n      }\n    }\n  }\n}\n\nreactiveclass Train(3) {\n  knownrebecs {\n    BridgeController controller;\n  }\n\n  statevars {\n    boolean onTheBridge;\n  }\n\n  msgsrv initial() {\n    onTheBridge = false;\n    self.Passed();\n  }\n\n  msgsrv YouMayPass() {\n    onTheBridge = true;\n    self.Passed();\n  }\n  \n  msgsrv Passed() {\n    onTheBridge = false;\n    controller.Leave();\n    self.ReachBridge();\n  }\n\n  msgsrv ReachBridge() {\n    controller.Arrive();\n  }\n}\n\nmain {\n  Train train1(theController):();\n  Train train2(theController):();\n  BridgeController theController(train1, train2):();\n}"
      -> "Two trains and a controller, taken from <a href=\"https://rebeca-lang.org/allprojects/CoreRebecaExamples/TrainController\">https://rebeca-lang.org/allprojects/CoreRebecaExamples/TrainController</a>.",
    "Leader Election HS (fix)" -> "reactiveclass Node(8) { \n    knownrebecs { \n      Node nodeL; \n        Node nodeR; \n    } \n      \n    statevars { \n        boolean monitor; \n        int myId; \n        int phase; \n        int monitorId; \n        boolean receivedLeft; \n        boolean receivedRight; \n    } \n  \n    msgsrv initial(int id) { \n        myId = id; \n        monitor = false; \n        monitorId = id; \n        phase = 1; \n        receivedLeft = false; \n        receivedRight = false; \n        self.arrive(); \n    } \n  \n    msgsrv arrive() { \n        nodeL.receive(myId, true, phase); \n        nodeR.receive(myId, true, phase); \n  } \n  \n  msgsrv receive(int msgId, boolean inOut, int hopCount) { \n    if ((sender==nodeL) &&  (inOut)) {\n      if (((msgId <monitorId)||(msgId==monitorId)) && (hopCount >1)) { \n        monitorId = msgId; \n              nodeR.receive (msgId, true, hopCount-1); \n            } else { \n        if (((msgId <monitorId)||(msgId==monitorId)) && (hopCount ==1)){ \n          monitorId=msgId; \n                    nodeL.receive (msgId, false,1); \n                } else { \n                    if (msgId == myId) { \n                      monitor = true; \n                      monitorId = myId; \n                  } \n                } \n      } \n        } \n            \n        if ((sender==nodeR) && (inOut)) { \n      if (((msgId <monitorId)||(msgId==monitorId)) && (hopCount >1)){ \n              monitorId=msgId; \n                nodeL.receive (msgId, true, hopCount-1); \n            } else { \n        if (((msgId <monitorId)||(msgId==monitorId)) && (hopCount ==1)){  \n                  monitorId=msgId; \n          nodeR.receive (msgId, false,1); \n                } else { \n                  if (msgId == myId) { \n                      monitor = true; \n                        monitorId = myId; \n                    } \n                } \n          } \n        } \n            \n        if ((sender==nodeL) && !(inOut) && !(msgId==myId)) { \n          nodeR.receive(msgId, false, 1);           \n        } \n            \n        if ((sender==nodeR) &&  !(inOut) && !(msgId==myId)) { \n          nodeL.receive(msgId, false, 1);           \n        } \n            \n    if ((sender==nodeL) && !(inOut) && ((msgId == myId) && (hopCount==1))) { \n          receivedLeft = true; \n        } \n    if (((sender==nodeR) && (msgId == myId)) && !(inOut) && (hopCount==1)) { \n          receivedRight = true; \n        }     \n            \n        if (receivedLeft && receivedRight&& (phase<3)){ \n          if(phase==2) { \n              monitor=true; \n            } else { \n                phase = phase * 2; \n                receivedLeft=false; \n                receivedRight=false; \n                nodeL.receive(myId, true, phase); \n                nodeR.receive(myId, true, phase); \n            } \n        } \n  } \n} \n  \n  \nmain { \n      Node node1(node4,node2):(1); \n      Node node2(node1,node3):(2); \n      Node node3(node2,node4):(3); \n      Node node4(node3,node1):(4); \n} "
      -> "From <a href=\"https://rebeca-lang.org/allprojects/CoreRebecaExamples/LeaderElection\">https://rebeca-lang.org/allprojects/CoreRebecaExamples/LeaderElection</a>.",
    "Leader Election LCR" -> "reactiveclass Node(8){\n  knownrebecs {\n    Node rightNode;\n  }\n  statevars {\n    boolean isLeader;\n    int myNumber;\n    int currentLeader;    \n  }\n  msgsrv initial(int n) {\n    myNumber = n;\n    currentLeader = n;\n    isLeader = false;\n    self.send();\n  }\n  \n  msgsrv ImLeader() {\n    self.ImLeader();\n    //The algorithm terminates here, but the leader keeps sending a msg to himself to avoid deadlock.\n  }\n  msgsrv send() {\n    rightNode.receive(currentLeader);\n  }\n  msgsrv receive(int n) {\n    if (n == myNumber) {\n      isLeader = true;\n      self.ImLeader();\n    }\n    else {\n      if (n > currentLeader) {\n        currentLeader = n;\n        self.send();\n      }\n      //else discard\n    }\n  }\n}\n\nmain { \n//Each node must have a unique identifier\n//In case of having more than three nodes or changing the leader to other node (rather than node1), you should change the property file too.\n   Node node0(node2):(4); \n   Node node1(node0):(20); \n   Node node2(node1):(10); \n} "
      -> "From <a href=\"https://rebeca-lang.org/allprojects/CoreRebecaExamples/LeaderElection\">https://rebeca-lang.org/allprojects/CoreRebecaExamples/LeaderElection</a>.",
    "Commit (unsupported-array)" -> "//Commit Protocol\nreactiveclass Node(10) {\n  knownrebecs {\n      Node node1;\n      Node node2;\n  }\n  statevars {\n      byte srvNo;\n    boolean recievedResults;\n    boolean creationAbility;\n    int recievedResultsCounter;\n    int expectedResultsCounter;\n    boolean[2] cooperatorKnownRebecs;\n    \n  }\n  \n  msgsrv initial(boolean nodeCreationAbility) {\n    creationAbility = nodeCreationAbility;\n    self.createTransaction();\n  }\n  \n  msgsrv createTransaction() {\n\n    boolean startTrans;\n    startTrans = ?(true, false);\n    if (startTrans && creationAbility) {\n      boolean dispatcher = false;\n      boolean result;\n\n      int i;\n      for(i = 0; i < 2; i = i + 1)\n        cooperatorKnownRebecs[i] = false;\n\n      recievedResultsCounter = 0;\n      recievedResults = true;\n\n\n      expectedResultsCounter = 0;\n\n            srvNo = 1;\n      dispatcher = ?(true, false);\n      if (dispatcher) {\n        cooperatorKnownRebecs[0] = true;\n        expectedResultsCounter = expectedResultsCounter + 1;\n        node1.startGlobalTransaction();\n      }\n\n      dispatcher = ?(true, false);\n      if (dispatcher) {\n        cooperatorKnownRebecs[1] = true;\n        expectedResultsCounter = expectedResultsCounter + 1;\n        node2.startGlobalTransaction();\n      }\n\n      expectedResultsCounter = expectedResultsCounter + 1;\n      result = ?(true, false);\n      self.cooperatorResponse(result);\n    }\n    else {\n      self.createTransaction();\n    }\n  }\n  \n  msgsrv startGlobalTransaction() {\n    boolean result;\n    result = ?(true, false);\n\n    if (sender == node1) {\n      node1.cooperatorResponse(result);\n    }\n    if (sender == node2) {\n      node2.cooperatorResponse(result);\n        }\n        \n  }\n\n  msgsrv cooperatorResponse(boolean result) {\n    recievedResultsCounter = recievedResultsCounter + 1;\n    if (!result)\n      recievedResults = false;\n\n    if (recievedResultsCounter == expectedResultsCounter) {\n            int i;\n      if (cooperatorKnownRebecs[0]) {\n        node1.applyResult(recievedResults);\n      }\n      if (cooperatorKnownRebecs[1]) {\n        node2.applyResult(recievedResults);\n      }\n\n      self.createTransaction();\n    }\n  }\n  \n\n  msgsrv applyResult(boolean result) {\n  }\n\n}\n\n\nmain {\n  Node node1(node2, node3):(true);\n  Node node2(node3, node1):(false);\n  Node node3(node1, node2):(true);\n}"
      -> "From <a href=\"https://rebeca-lang.org/allprojects/CoreRebecaExamples/CommitProblem\">https://rebeca-lang.org/allprojects/CoreRebecaExamples/CommitProblem</a>.",
    "Commit (adapted)" -> "// Adapted version without arrays\n//Commit Protocol\nreactiveclass Node(10) {\n  knownrebecs {\n      Node node1;\n      Node node2;\n  }\n  statevars {\n      byte srvNo;\n    boolean recievedResults;\n    boolean creationAbility;\n    int recievedResultsCounter;\n    int expectedResultsCounter;\n    boolean cooperatorKnownRebecs0;\n    boolean cooperatorKnownRebecs1;\n    \n  }\n  \n  msgsrv initial(boolean nodeCreationAbility) {\n    creationAbility = nodeCreationAbility;\n    self.createTransaction();\n  }\n  \n  msgsrv createTransaction() {\n\n    //boolean startTrans;\n    startTrans = ?(true, false);\n    if (startTrans && creationAbility) {\n      //boolean dispatcher = false;\n      //boolean result;\n\n      //int i;\n      //for(i = 0; i < 2; i = i + 1)\n      //  cooperatorKnownRebecs[i] = false;\n      cooperatorKnownRebecs0 = false;\n      cooperatorKnownRebecs1 = false;\n\n      recievedResultsCounter = 0;\n      recievedResults = true;\n\n\n      expectedResultsCounter = 0;\n\n            srvNo = 1;\n      dispatcher = ?(true, false);\n      if (dispatcher) {\n        cooperatorKnownRebecs0 = true;\n        expectedResultsCounter = expectedResultsCounter + 1;\n        node1.startGlobalTransaction();\n      }\n\n      dispatcher = ?(true, false);\n      if (dispatcher) {\n        cooperatorKnownRebecs1 = true;\n        expectedResultsCounter = expectedResultsCounter + 1;\n        node2.startGlobalTransaction();\n      }\n\n      expectedResultsCounter = expectedResultsCounter + 1;\n      result = ?(true, false);\n      self.cooperatorResponse(result);\n    }\n    else {\n      self.createTransaction();\n    }\n  }\n  \n  msgsrv startGlobalTransaction() {\n    //boolean result;\n    result = ?(true, false);\n\n    if (sender == node1) {\n      node1.cooperatorResponse(result);\n    }\n    if (sender == node2) {\n      node2.cooperatorResponse(result);\n        }\n        \n  }\n\n  msgsrv cooperatorResponse(boolean result) {\n    recievedResultsCounter = recievedResultsCounter + 1;\n    if (!result)\n      recievedResults = false;\n\n    if (recievedResultsCounter == expectedResultsCounter) {\n            //int i;\n      if (cooperatorKnownRebecs0) {\n        node1.applyResult(recievedResults);\n      }\n      if (cooperatorKnownRebecs1) {\n        node2.applyResult(recievedResults);\n      }\n\n      self.createTransaction();\n    }\n  }\n  \n\n  msgsrv applyResult(boolean result) {\n  }\n\n}\n\n\nmain {\n  Node node1(node2, node3):(true);\n  Node node2(node3, node1):(false);\n  Node node3(node1, node2):(true);\n}"
