    "Prod-Cons (larger)" -> "reactiveclass BufferManager(4) {\n  knownrebecs {\n    Producer producer;\n    Consumer consumer;\n  }\n\n  statevars {\n    boolean empty;\n    boolean full;\n    boolean producerWaiting;\n    boolean consumerWaiting;\n    int bufferlenght;\n    int nextProduce;\n    int nextConsume;    \n  }\n\n  msgsrv initial() {\n    bufferlenght = 2;\n    empty = true;\n    full = false;\n    producerWaiting = false;\n    consumerWaiting = false;\n    nextProduce = 0;\n    nextConsume = 0;\n  }\n\n  msgsrv giveMeNextProduce() {\n    if (!full)  {\n      producer.produce(nextProduce);\n    } \n  }\n\n  msgsrv giveMeNextConsume() {\n    if (!empty) {\n      consumer.consume(nextConsume);\n    } \n       else {\n      consumerWaiting = true;\n    }\n  }\n\n  msgsrv ackProduce() {\n    nextProduce = (nextProduce + 1) %\n                    bufferlenght;\n    if (nextProduce == nextConsume) {\n      full = true;\n    }\n    empty = false;\n    if (consumerWaiting) {\n      consumer.consume(nextConsume);\n      consumerWaiting = false;\n    }\n  }\n\n  msgsrv ackConsume() {\n    nextConsume = (nextConsume + 1) %\n                    bufferlenght;\n    if (nextConsume == nextProduce) {\n      empty = true;\n    }\n    full = false;\n    if (producerWaiting) {\n      producer.produce(nextProduce);\n      producerWaiting = false;\n    }\n  }\n}\n\nreactiveclass Producer(2) {\n  knownrebecs {\n    BufferManager buffer;\n  }\n\n  statevars {\n  }\n\n  msgsrv initial() {\n    self.beginProduce();\n  }\n  \n  msgsrv produce(int bufNum) {\n    buffer.ackProduce();\n    self.beginProduce();\n  }\n\n  msgsrv beginProduce() {\n    buffer.giveMeNextProduce();\n  }\n}\n\nreactiveclass Consumer(2) {\n  knownrebecs {\n    BufferManager buffer;    \n  }\n\n  statevars {\n  }\n\n  msgsrv initial() {\n    self.beginConsume();\n  }\n\n  msgsrv consume(int bufNum) {\n    buffer.ackConsume();\n    self.beginConsume();  \n  }\n  \n  msgsrv beginConsume() {\n    buffer.giveMeNextConsume();\n  }\n\n}\n\nmain { \n  BufferManager buffer(producer, consumer):();\n  Producer producer(buffer):();\n  Consumer consumer(buffer):();\n}"
