  private val sosRules: String =
    """The operational rules that we use to reduce programs are provided below.
      |These are explained, e.g. in
      |<a href="http://dx.doi.org/10.1016/j.scico.2014.07.005" target="_blank">this SCP publication (2014)</a>.
      |<pre>
      |WHEN
      |  (σ_r(m), // statements in method m
      |   σ_r[now=max(TT,σ_r(now)),[arg=v],sender=s], // initial state of r
      |   Env,    // state of other rebecs
      |   B)      // initial outgoing messages
      |  EVALUATES TO
      |  (σ'_r,   // updated state of r
      |   Env',   // updatred state of other rebecs (possibly with new rebecs)
      |   B')     // updated outgoing messages
      |IF
      |  TT≤min(B) ∧              // r is the next one to execute (based on time)
      |  σ_r(now)≤DL              // r can still execute
      |THEN
      |  ({σ_r} ∪ Env,            // take σ_r from Env
      |   {(r,m(v),s,TT,DL)} ∪ B) // take a message from B
      |  →
      |  ({σ'_r} ∪ Env',          // update state of r and set of other rebecs
      |   B')                     // update outgoing messages
      |</pre>""".stripMargin

  override val documentation: Documentation = List(
    languageName -> "More information on the syntax of rebecaOS" ->
      s"""<p>The syntax and timed (static) semantics for a Rebeca program can be found, e.g., in
        |<a href="http://dx.doi.org/10.1016/j.scico.2014.07.005" target="_blank">this SCP publication (2014)</a>.</p>
        |
        |<p>${sosRules}</p>
        |""".stripMargin,
    "Build LTS" -> "More information on the operational rules used here" -> sosRules,
    "Build LTS (explore)" -> "More information on the operational rules used here" -> sosRules,
    "Run semantics" -> "More information on the operational rules used here" -> sosRules,
    "Run semantics (sequence chart)" -> "More information on the sequence charts." ->
      ("<p>Builds interactively a sequence chart. <ul><li>Solid arrows represent messages that are both <strong>sent and received</strong>." +
        "<li>Dashed arrows represent pending messages that are <strong>sent but not received.</strong>.</ul></p>" +
      s"\n <p> $sosRules </p>"),
    "Reachability checks" -> "More information on how to check if a property is reachable." ->
      ("<p> If at the end of your program you include reachability properties of the form <code>reaches EXPR;</code>, this widget will display the results from searching for a state that satisfies <code>EXPR</code>. " +
        "</p><p> The <code>EXPR</code> uses the same syntax as expressions in Rebeca, but variables must be quantified by the name of the rebec that owns it. " +
        "E.g., <code>reaches ex1.counter==1</code> searches for a state where the <code>counter</code> variable of the <code>ex1</code> rebec is equal to 1. The special predicate <code>deadlock</code> holds when the state has no outgoing transitions. The search stops after traversing around 5000 transitions.</p>"),
  )
